"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """Return the fraction of transcripts flagged True (SPEC.md section 1)."""
    if not events:
        return 0.0
    return sum(1 for event in events if event.get("flagged") is True) / len(events)


def pooled_flag_rate(groups):
    """Return the transcript-weighted flag rate across groups (section 2)."""
    total = 0
    flagged = 0
    for events in groups.values():
        total += len(events)
        flagged += sum(1 for event in events if event.get("flagged") is True)
    return flagged / total if total else 0.0


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (section 3)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """Map each group to its flag rate, with empty groups mapped to None."""
    return {
        name: (monitor_flag_rate(events) if events else None)
        for name, events in sorted(groups.items())
    }


def longest_flag_streak(daily_counts):
    """Return the longest run of consecutive entries greater than zero."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

"""Loading and preparing safety-monitor transcript logs."""


def parse_transcript_log(lines):
    """Parse transcript log lines according to SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep the last transcript per id and sort by day, then id (section 5)."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts on every day in the inclusive range (section 6)."""
    if end_day < start_day:
        return []
    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event.get("flagged") is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]

"""Reporting helpers for safety-monitor evaluation results."""

from safety_evals.loader import daily_flag_counts
from safety_evals.metrics import (
    flags_in_window,
    monitor_flag_rate,
    pooled_flag_rate,
)


def monitor_summary(groups, days):
    """Return pooled rate, recent flagged count, and nonempty group count."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        counts = daily_flag_counts(all_events, first_day, last_day)
        recent = flags_in_window(counts, days)
    else:
        recent = 0
    return {
        "rate": round(pooled_flag_rate(groups), 3),
        "recent": recent,
        "groups": sum(bool(events) for events in groups.values()),
    }


def top_flagged_groups(groups, n):
    """Return up to n nonempty groups by flag rate, with name-based tie breaks."""
    ranked = [
        (name, monitor_flag_rate(events))
        for name, events in groups.items()
        if events
    ]
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return [name for name, _ in ranked[:n]]

