def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


def test_dedupe_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "same", "day": 1, "flagged": True},
        {"id": "other", "day": 2, "flagged": False},
        {"id": "same", "day": 3, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_pooled_flag_rate_weights_each_transcript():
    assert pooled_flag_rate({
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }) == 0.5


def test_flags_in_window_uses_exact_last_days():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_transcript_log_fields_and_skipped_lines():
    assert parse_transcript_log([
        "  # ignored comment",
        "   ",
        " x1 , 3 , ",
        "x2,4,0",
    ]) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
    ]


def test_parse_transcript_log_error_reports_original_line_number():
    try:
        parse_transcript_log(["# comment", "", "bad,not-a-day,1"])
    except ValueError as error:
        assert "line 3" in str(error)
    else:
        raise AssertionError("expected ValueError")


def test_daily_counts_cover_range_and_ignore_outside_days():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": None},
        {"day": 3, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 3) == []


def test_group_reporting_and_summary_follow_spec():
    groups = {
        "z": [{"id": "z1", "day": 1, "flagged": True}],
        "a": [{"id": "a1", "day": 1, "flagged": False}],
        "empty": [],
    }
    assert flag_rate_by_group(groups) == {"a": 0.0, "empty": None, "z": 1.0}
    assert top_flagged_groups(groups, 3) == ["z", "a"]
    assert monitor_summary(groups, 1) == {"rate": 0.5, "recent": 1, "groups": 2}


def test_longest_streak_requires_positive_counts():
    assert longest_flag_streak([1, -1, 2, 3, 0]) == 2
    assert longest_flag_streak([]) == 0
